    for i in range(n - 1):
        prev_layer = K[i]
        size_prev = len(prev_layer)
        new_layer = [[0] * (i + 2) for _ in range(size_prev + i + 1)]
        K.append(new_layer)
        for j, row in enumerate(prev_layer):
            for k, val in enumerate(row):
                for h in range(i + 1):
                    new_layer[j + h][k] = (new_layer[j + h][k] + val) % M
                new_layer[j + i + 1][i + 1] = (new_layer[j + i + 1][i + 1] + val) % M

    C = nCr_mod(n, M)
    total = 0
    for i in range(1, n):
        layer = K[i]
        ni = len(layer)
        mi = len(layer[0])
        S = [[layer[j][k] for k in range(mi)] for j in range(ni)]
        for j in range(ni):
            for k in reversed(range(mi - 1)):
                S[j][k] = (S[j][k] + S[j][k + 1]) % M
        for j in range(1, ni):
            for k in range(mi):
                S[j][k] = (S[j][k] + S[j - 1][k]) % M
        sum_i = 0
        for j in range(1, ni):
            for k in range(mi - 1):
                sum_i += (layer[j][k] * S[j - 1][k + 1]) % M
                sum_i %= M
        c = C[i + 1]
        sum_i = (sum_i * c) % M
        total = (total + sum_i) % M
    return total


