import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] input = readTwoInts(scanner);
        int n = input[0];
        int m = input[1];
        System.out.println(calculate(n, m));
        scanner.close();
    }

    private static int[] readTwoInts(Scanner scanner) {
        int a = scanner.nextInt();
        int b = scanner.nextInt();
        return new int[]{a, b};
    }

    private static int gcdExtended(int a, int b) {
        int r1 = a, r2 = b;
        int s1 = 1, s2 = 0;
        int t1 = 0, t2 = 1;
        while (r2 != 0) {
            int q = r1 / r2;
            int rTemp = r1 - q * r2;
            r1 = r2;
            r2 = rTemp;

            int sTemp = s1 - q * s2;
            s1 = s2;
            s2 = sTemp;

            int tTemp = t1 - q * t2;
            t1 = t2;
            t2 = tTemp;
        }
        return r1;
    }

    private static int[] nCrMod(int n, int M) {
        int[] C = new int[n + 1];
        C[n] = 1;
        for (int i = n - 1; i >= 0; i--) {
            C[i] = (int)((long)C[i + 1] * (i + 1) % M);
            if (C[i] == 0) {
                break;
            }
        }
        return C;
    }

    private static int calculate(int n, int M) {
        // Initialize K as a list of lists of lists
        // Using ArrayList for dynamic sizing
        java.util.List<java.util.List<int[]>> K = new java.util.ArrayList<>();
        // Each element in K is a list of int arrays (rows)
        java.util.List<int[]> firstLayer = new java.util.ArrayList<>();
        firstLayer.add(new int[]{1});
        K.add(firstLayer);

        for (int i = 0; i < n - 1; i++) {
            java.util.List<int[]> prevLayer = K.get(i);
            int sizePrev = prevLayer.size();
            java.util.List<int[]> newLayer = new java.util.ArrayList<>();
            int newLayerSize = sizePrev + i + 1;
            for (int j = 0; j < newLayerSize; j++) {
                newLayer.add(new int[i + 2]);
            }
            K.add(newLayer);
            for (int j = 0; j < sizePrev; j++) {
                int[] row = prevLayer.get(j);
                for (int k = 0; k < row.length; k++) {
                    int val = row[k];
                    for (int h = 0; h < i + 1; h++) {
                        int[] targetRow = newLayer.get(j + h);
                        targetRow[k] = (targetRow[k] + val) % M;
                    }
                    int[] targetRow = newLayer.get(j + i + 1);
                    targetRow[i + 1] = (targetRow[i + 1] + val) % M;
                }
            }
        }

        int[] C = nCrMod(n, M);
        long total = 0;
        for (int i = 1; i < n; i++) {
            java.util.List<int[]> layer = K.get(i);
            int ni = layer.size();
            int mi = layer.get(0).length;

            int[][] S = new int[ni][mi];
            for (int j = 0; j < ni; j++) {
                System.arraycopy(layer.get(j), 0, S[j], 0, mi);
            }

            // Compute suffix sums for each row
            for (int j = 0; j < ni; j++) {
                for (int k = mi - 2; k >= 0; k--) {
                    S[j][k] = (S[j][k] + S[j][k + 1]) % M;
                }
            }

            // Compute prefix sums over rows
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi; k++) {
                    S[j][k] = (S[j][k] + S[j - 1][k]) % M;
                }
            }

            long sum_i = 0;
            for (int j = 1; j < ni; j++) {
                for (int k = 0; k < mi - 1; k++) {
                    long product = ((long)layer.get(j)[k] * S[j - 1][k + 1]) % M;
                    sum_i = (sum_i + product) % M;
                }
            }

            int c = C[i + 1];
            sum_i = (sum_i * c) % M;
            total = (total + sum_i) % M;
        }
        return (int)total;
    }
}
